// Live tuning overlay (docs/research/malleable-dev-flow.md P2). Knobs are generated by walking the shipped content tables; an
// override set is a flat {knobId: value} map applied to a deep CLONE of the tables, so the shipped tables are never mutated and
// the sim stays deterministic for whatever content it is handed. Bread/dip knobs are keyed by the first non-zero value across
// the five levels and scale every level by the same ratio (levels are cumulative ladders, so editing L1 alone would not stick).
import { bossAtOf, CRUISE, CRUISE_LATE, LIVE_CAP } from './director';
import type { Content } from './types';

export type Overrides = Record<string, number>;
export type Knob = { id: string; section: string; label: string; def: number; min: number; max: number; step: number };

/** Presentation constants live in src/game/phaser; their defaults are mirrored here so the panel can list them. */
export const PRES_DEFAULTS = { hover: 1, wobble: 0.55, finale: 1 } as const;

const num = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);
const knob = (id: string, section: string, label: string, def: number, whole = def === Math.round(def) && Math.abs(def) >= 1 ? true : false): Knob => ({
  id, section, label, def,
  min: whole ? Math.max(1, Math.floor(def * 0.25)) : def * 0.25,
  max: whole ? Math.ceil(def * 4) : def * 4,
  step: whole ? 1 : def >= 10 ? 0.5 : def >= 1 ? 0.05 : 0.01,
});
const levelKeys = (levels: Record<string, unknown>[]): [string, number][] => {
  const out: [string, number][] = [];
  for (const key of new Set(levels.flatMap((l) => Object.keys(l)))) {
    const first = levels.map((l) => l[key]).find((v) => num(v) && v !== 0);
    if (num(first)) out.push([key, first]);
  }
  return out;
};

export function tuneKnobs(content: Content): Knob[] {
  const ks: Knob[] = [];
  for (const b of Object.values(content.breads))
    for (const [key, def] of levelKeys(b.levels as unknown as Record<string, unknown>[])) ks.push(knob(`breads.${b.id}.${key}`, `Bread: ${b.name}`, key, def));
  for (const d of Object.values(content.dips))
    for (const [key, def] of levelKeys(d.levels as unknown as Record<string, unknown>[])) ks.push(knob(`dips.${d.id}.${key}`, `Dip: ${d.name}`, key, def));
  ks.push(knob('enemies.all.hp', 'Enemies', 'hp x (all)', 1, false), knob('enemies.all.speed', 'Enemies', 'speed x (all)', 1, false));
  for (const e of Object.values(content.enemies))
    ks.push(knob(`enemies.${e.id}.hp`, 'Enemies', `${e.name} hp`, e.hp), knob(`enemies.${e.id}.speed`, 'Enemies', `${e.name} speed`, e.speed));
  ks.push(knob('director.cruise', 'Director', 'stall speed, start (m/s)', CRUISE), knob('director.cruiseLate', 'Director', 'stall speed, at boss (m/s)', CRUISE_LATE), knob('director.pressure', 'Director', 'pressure ramp x', 1, false),
    knob('director.liveCap', 'Director', 'LIVE_CAP', LIVE_CAP));
  for (const c of content.chapters) ks.push(knob(`chapters.${c.id}.bossAt`, 'Director', `${c.name} bossAt (m)`, bossAtOf(c)));
  ks.push({ id: 'mode.free', section: 'Mode', label: 'free movement (0 counter, 1 free)', def: 0, min: 0, max: 1, step: 1 });
  ks.push(knob('pres.hover', 'Look', 'prata hover height x', PRES_DEFAULTS.hover, false), knob('pres.wobble', 'Look', 'wobble amount', PRES_DEFAULTS.wobble, false),
    knob('pres.finale', 'Look', 'finale duration x', PRES_DEFAULTS.finale, false));
  return ks;
}

/** Only values that differ from their knob default and sit inside its range; anything else (stale ids, junk) is dropped. */
export function cleanOverrides(raw: unknown, knobs: Knob[]): Overrides {
  const out: Overrides = {};
  if (!raw || typeof raw !== 'object') return out;
  const by = new Map(knobs.map((k) => [k.id, k]));
  for (const [id, v] of Object.entries(raw as Record<string, unknown>)) {
    const k = by.get(id);
    if (k && num(v) && v !== k.def) out[id] = Math.min(k.max, Math.max(k.min, v));
  }
  return out;
}

const scaleLevels = (levels: object[], key: string, ratio: number, whole: boolean) => {
  for (const l of levels as Record<string, number>[]) if (num(l[key])) l[key] = whole ? Math.round(l[key] * ratio) : l[key] * ratio;
};

/** A tuned deep copy of `base`. With no overrides returns `base` itself (zero cost, zero risk for normal play). */
export function applyTune(base: Content, overrides: Overrides): Content {
  const ids = Object.keys(overrides);
  if (!ids.length) return base;
  const c: Content = structuredClone(base);
  const knobs = new Map(tuneKnobs(base).map((k) => [k.id, k]));
  const get = (id: string) => overrides[id];
  const tune: NonNullable<Content['tune']> = {};
  for (const id of ids) {
    const k = knobs.get(id);
    if (!k) continue;
    const [kind, name, key] = id.split('.');
    const v = overrides[id];
    if (kind === 'breads' || kind === 'dips') scaleLevels(((kind === 'breads' ? c.breads : c.dips) as Record<string, { levels: object[] }>)[name].levels, key, v / k.def, Number.isInteger(k.def));
    else if (kind === 'enemies' && name !== 'all') (c.enemies[name] as unknown as Record<string, number>)[key] = v;
    else if (kind === 'chapters') c.chapters.find((ch) => ch.id === name)!.bossAt = v;
    else if (id === 'director.cruise') tune.cruise = v;
    else if (id === 'director.cruiseLate') tune.cruiseLate = v;
    else if (id === 'director.pressure') tune.pressure = v;
    else if (id === 'director.liveCap') tune.liveCap = v;
    else if (id === 'mode.free') tune.controlMode = v >= 0.5 ? 'free' : 'counter';
  }
  const hpAll = get('enemies.all.hp'), spAll = get('enemies.all.speed');
  if (hpAll !== undefined || spAll !== undefined)
    for (const e of Object.values(c.enemies)) { e.hp *= hpAll ?? 1; e.speed *= spAll ?? 1; }
  if (Object.keys(tune).length) c.tune = tune;
  return c;
}
